public class RepairMissingXwgSchools{public static void main(String[]a)throws Exception{String y=Files.readString(Path.of("src/main/resources/application.yml"),StandardCharsets.UTF_8);String u=v(y,"url").replace("192.168.3.5","127.0.0.1");JsonNode rows=new ObjectMapper().readTree(Path.of("tmp/xueweigui-schools-20260914.json").toFile()).path("schools");try(Connection c=DriverManager.getConnection(u,v(y,"username"),v(y,"password"))){c.setAutoCommit(false);int n=0;try(var q=c.prepareStatement("SELECT COUNT(*) FROM school WHERE xueweigui_school_id=?")){for(JsonNode row:rows){var s=ImportXueweiguiSchools.parse(row);q.setInt(1,s.sid());try(var r=q.executeQuery()){r.next();if(r.getInt(1)==0){ImportXueweiguiSchools.insert(c,s);System.out.println("INSERT_MISSING\t"+s.sid()+"\t"+s.name());n++;}}}}c.commit();try(var s=c.createStatement();var r=s.executeQuery("SELECT COUNT(*) total,COUNT(DISTINCT xueweigui_school_id) source_ids,SUM(xueweigui_school_id IS NULL) legacy,SUM(is_active=1) active FROM school")){r.next();System.out.printf("inserted=%d total=%d source_ids=%d legacy=%d active=%d%n",n,r.getInt(1),r.getInt(2),r.getInt(3),r.getInt(4));if(r.getInt(2)!=148)throw new IllegalStateException("expected 148 source ids");}}}static String v(String y,String k){var m=Pattern.compile("(?m)^\\s*"+k+":\\s*([^\\r\\n#]+)").matcher(y);m.find();String z=m.group(1).trim();var p=Pattern.compile("\\$\\{([^:}]+)(?::([^}]*))?}").matcher(z);if(!p.matches())return z;String e=System.getenv(p.group(1));return e!=null&&!e.isBlank()?e:p.group(2);}}
